/**
 * Component Helpers for TUI
 *
 * Provides static create methods for pi-tui components.
 * This bridges the gap between the React-like API used in render functions
 * and the actual pi-tui component classes.
 */

import { Box, Text } from "@mariozechner/pi-tui";

export interface TextOptions {
  color?: string;
  bold?: boolean;
  italic?: boolean;
  dim?: boolean;
  underline?: boolean;
  tooltip?: string;
}

export interface BoxOptions {
  children?: any[];
  border?: {
    type?: string;
    color?: string;
  };
  padding?: number;
  margin?: number | { top?: number; bottom?: number; left?: number; right?: number };
}

/**
 * Create a Text component with options
 */
export function createText(text: string, options: TextOptions = {}): Text {
  // Apply styling via ANSI codes in the text itself
  let styledText = text;

  if (options.dim) {
    styledText = `\x1b[2m${styledText}\x1b[0m`;
  }
  if (options.italic) {
    styledText = `\x1b[3m${styledText}\x1b[0m`;
  }
  if (options.bold) {
    styledText = `\x1b[1m${styledText}\x1b[0m`;
  }
  if (options.underline) {
    styledText = `\x1b[4m${styledText}\x1b[0m`;
  }
  if (options.color) {
    const colorCodes: Record<string, string> = {
      red: "31",
      green: "32",
      yellow: "33",
      blue: "34",
      magenta: "35",
      cyan: "36",
      white: "37",
      gray: "90",
      grey: "90",
    };
    const code = colorCodes[options.color.toLowerCase()] || "37";
    styledText = `\x1b[${code}m${styledText}\x1b[0m`;
  }

  return new Text(styledText);
}

/**
 * Create a Box component with options
 */
export function createBox(options: BoxOptions = {}): Box {
  const padding = typeof options.padding === "number" ? options.padding : 1;
  const box = new Box(padding, padding);

  if (options.children) {
    for (const child of options.children) {
      if (child instanceof Text || child instanceof Box) {
        box.addChild(child);
      } else if (typeof child === "string") {
        box.addChild(new Text(child));
      }
    }
  }

  return box;
}

// Augment Text and Box classes with static create methods
(Text as any).create = createText;
(Box as any).create = createBox;

