 * Render multiple thinking blocks
 */
export function renderThinkingBlocks(
  blocks: ThinkingBlock[],
  options: ThinkingDisplayOptions = {},
): any[] {
  return blocks.map((block) => renderThinkingBlock(block, options));
}


