/**
 * Check if a value is truthy
 */
function isTruthy(value: string | undefined): boolean {
  if (value === undefined || value === "") {
    return false;
  }
  const lower = value.toLowerCase();
  return lower !== "false" && lower !== "0" && lower !== "no";
}

