 * Check for predictions (call periodically or on triggers)
 */
export async function checkPredictions(): Promise<
  Array<{
    action: string;
    message: string;
    priority: string;
    confidence: number;
  }>
> {
  ensureInitialized();
  if (!predictiveEngine) {
    return [];
